use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    ensures
        // For all i,j within bounds:
        // result.0[i][j] == x[j]
        // result.1[i][j] == y[i]
        forall(|i: int, j: int| (0 <= i && i < y.len() as int && 0 <= j && j < x.len() as int) ==>
            result.0[i as usize][j as usize] == x[j as usize] &&
            result.1[i as usize][j as usize] == y[i as usize]
        )
{
    let m = x.len();
    let n = y.len();

    let mut grid_x: Vec<Vec<f32>> = Vec::with_capacity(n);
    let mut grid_y: Vec<Vec<f32>> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            grid_x.len() == i,
            grid_y.len() == i,
            forall(|k: int| (0 <= k && k < i as int) ==>
                grid_x[k as usize].len() == m &&
                // each row of grid_x equals x
                forall(|j: int| (0 <= j && j < m as int) ==> grid_x[k as usize][j as usize] == x[j as usize]) &&
                grid_y[k as usize].len() == m &&
                // each row of grid_y is y[k]
                forall(|j: int| (0 <= j && j < m as int) ==> grid_y[k as usize][j as usize] == y[k as usize])
            )
        decreases n - i,
    {
        // Clone x for grid_x
        grid_x.push(x.clone());

        // Prepare row for grid_y with length m, each element y[i]
        let mut row_y: Vec<f32> = Vec::with_capacity(m);
        let mut j: usize = 0;
        while j < m
            invariant
                j <= m,
                row_y.len() == j,
                forall(|idx: int| (0 <= idx && idx < j as int) ==> row_y[idx as usize] == y[i]),
            decreases m - j,
        {
            row_y.push(y[i]);
            j += 1;
        }

        grid_y.push(row_y);
        i += 1;
    }

    (grid_x, grid_y)
}

}
